import java.util.*;
import java.math.*;

public class Main {
    static String toString(String s) {
        return "\"" + s + "\"";
    }

    static String toString(char[] s) {
        return toString(new String(s));
    }

    static String toString(boolean b) {
        return b ? "true" : "false";
    }

    static String toString(List<Boolean> v) {
        StringBuilder res = new StringBuilder("{");
        boolean first = true;
        for (Boolean b : v) {
            if (!first) res.append(", ");
            first = false;
            res.append(toString(b));
        }
        res.append("}");
        return res.toString();
    }

    static String toString(BitSet v, int N) {
        StringBuilder res = new StringBuilder();
        for (int i = 0; i < N; i++) {
            res.append(v.get(i) ? '1' : '0');
        }
        return res.toString();
    }

    static <T> String toString(Collection<T> v) {
        StringBuilder res = new StringBuilder("{");
        boolean first = true;
        for (T x : v) {
            if (!first) res.append(", ");
            first = false;
            res.append(toString(x));
        }
        res.append("}");
        return res.toString();
    }

    static <A, B> String toString(Pair<A, B> p) {
        return "(" + toString(p.first) + ", " + toString(p.second) + ")";
    }

    static <A, B, C> String toString(Tuple3<A, B, C> p) {
        return "(" + toString(p.first) + ", " + toString(p.second) + ", " + toString(p.third) + ")";
    }

    static <A, B, C, D> String toString(Tuple4<A, B, C, D> p) {
        return "(" + toString(p.first) + ", " + toString(p.second) + ", " + toString(p.third) + ", " + toString(p.fourth) + ")";
    }

    static void debugOut(Object... args) {
        // No output to stderr as per original code
    }

    static <T> T modularInverse(T a, T m) {
        BigInteger A = new BigInteger(a.toString());
        BigInteger M = new BigInteger(m.toString());
        return (T) (Object) A.modInverse(M);
    }

    static class ModType4 {
        static int value;
    }

    static class Num4 {
        int val;

        Num4() {
            this.val = 0;
        }

        <U> Num4(U x) {
            this.val = normalize(x);
        }

        static int normalize(Object x) {
            long v;
            if (x instanceof Integer) {
                v = (Integer) x;
            } else if (x instanceof Long) {
                v = (Long) x;
            } else if (x instanceof BigInteger) {
                v = ((BigInteger) x).longValue();
            } else {
                v = Long.parseLong(x.toString());
            }
            int m = ModType4.value;
            v = v % m;
            if (v < 0) v += m;
            return (int) v;
        }

        Num4 add(Num4 other) {
            int res = this.val + other.val;
            if (res >= ModType4.value) res -= ModType4.value;
            return new Num4(res);
        }

        Num4 subtract(Num4 other) {
            int res = this.val - other.val;
            if (res < 0) res += ModType4.value;
            return new Num4(res);
        }

        Num4 multiply(Num4 other) {
            long res = (long) this.val * other.val;
            res %= ModType4.value;
            return new Num4((int) res);
        }

        Num4 divide(Num4 other) {
            return this.multiply(new Num4(modInverse(other.val, ModType4.value)));
        }

        static int modInverse(int a, int m) {
            return new BigInteger(String.valueOf(a)).modInverse(BigInteger.valueOf(m)).intValue();
        }

        @Override
        public String toString() {
            return Integer.toString(val);
        }
    }

    static class Pair<A, B> {
        A first;
        B second;

        Pair(A a, B b) {
            this.first = a;
            this.second = b;
        }
    }

    static class Tuple3<A, B, C> {
        A first;
        B second;
        C third;

        Tuple3(A a, B b, C c) {
            this.first = a;
            this.second = b;
            this.third = c;
        }
    }

    static class Tuple4<A, B, C, D> {
        A first;
        B second;
        C third;
        D fourth;

        Tuple4(A a, B b, C c, D d) {
            this.first = a;
            this.second = b;
            this.third = c;
            this.fourth = d;
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int m = sc.nextInt();
        ModType4.value = sc.nextInt();

        List<Num4> fact = new ArrayList<>();
        List<Num4> inv_fact = new ArrayList<>();
        fact.add(new Num4(1));
        inv_fact.add(new Num4(1));

        // Function for combination
        java.util.function.BiFunction<Integer, Integer, Num4> C = (x, y) -> {
            int sz = Math.max(x, y);
            while (fact.size() <= sz) {
                int size = fact.size();
                fact.add(fact.get(fact.size() - 1).multiply(new Num4(size)));
                inv_fact.add(fact.get(fact.size() - 1).divide(new Num4(ModType4.value)));
            }
            if (y < 0 || y > x) return new Num4(0);
            return fact.get(x).multiply(inv_fact.get(y)).multiply(inv_fact.get(x - y));
        };

        Num4[] ways_arr = new Num4[m + 1];
        Num4[] ways_count = new Num4[m + 1];
        for (int i = 0; i <= m; i++) {
            ways_arr[i] = new Num4(0);
            ways_count[i] = new Num4(0);
        }
        ways_count[0] = new Num4(1);

        for (int i = 1; i <= m; i++) {
            for (int j = 0; j < i; j++) {
                int l = j;
                int r = i - 1 - j;
                Num4 c = C.apply(l + r, l);
                Num4 add = new Num4(l).multiply(new Num4(l + 1)).add(new Num4(r).multiply(new Num4(r + 1))).divide(new Num4(2));
                ways_arr[i] = ways_arr[i].add(ways_count[l].multiply(ways_count[r]).multiply(c).multiply(new Num4(l + r + 2)));
                ways_count[i] = ways_count[i].add(ways_count[l].multiply(ways_count[r]).multiply(c).multiply(add));
            }
        }

        Num4[][] dp = new Num4[n + 1][m + 1];
        Num4[][] ways_dp = new Num4[n + 1][m + 1];
        for (int i = 0; i <= n; i++) {
            for (int j = 0; j <= m; j++) {
                dp[i][j] = new Num4(0);
                ways_dp[i][j] = new Num4(0);
            }
        }
        ways_dp[0][0] = new Num4(1);

        for (int i = 1; i <= n; i++) {
            for (int s = 0; s <= Math.min(m, i); s++) {
                if (s == i) {
                    dp[i][s] = new Num4(ways_count[s].val);
                    continue;
                }
                for (int d = 1; d <= s + 1; d++) {
                    if (i - d >= 0 && s + 1 - d >= 0) {
                        Num4 ft = dp[i - d][s + 1 - d];
                        Num4 way = ways_dp[i - d][s + 1 - d];
                        int add = d - 1;
                        Num4 c = C.apply(s, add);
                        ways_dp[i][s] = ways_dp[i][s].add(way.multiply(ways_count[add]).multiply(c));
                        Num4 term1 = way.multiply(new Num4(ways_count[add]));
                        Num4 term2 = ways_dp[i - d][s + 1 - d].multiply(ft);
                        Num4 sum = term1.add(term2);
                        dp[i][s] = dp[i][s].add(sum.multiply(c));
                    }
                }
            }
        }

        System.out.println(dp[n][m]);
        sc.close();
    }
}
